package vn.lutrinh.app.domain.usecase

/**
 * The share page's own copy of the numerals (R18, docs/08 §8): Barlow Condensed Bold cut down to
 * `0-9 . , : - – / + %` and a space (2.3 KB, WOFF2, base64), so the numbers keep their shape on a
 * phone or computer that has no Barlow. Source: `app/src/main/res/font/barlow_condensed_bold.ttf`
 * (© 2017 The Barlow Project Authors, SIL OFL 1.1, `assets/licenses/BarlowCondensed-OFL.txt`; the
 * licence allows embedding a modified subset). Regenerate with fonttools:
 * `pyftsubset barlow_condensed_bold.ttf --text="0123456789.,:-–/+% " --flavor=woff2
 * --layout-features='tnum,lnum' --no-hinting --desubroutinize`, then base64 without line breaks.
 */
internal object BarlowDigits {
    const val WOFF2_BASE64 = ""
}
